module top_module(
    input reset,

    input write_clk,
    input [BUFFER_ADDR_WIDTH-1:0] write_addr,
    input [DATA_WIDTH-1:0] write_data,
    input write_enable,

    input read_clk,
    input [BUFFER_ADDR_WIDTH-1:0] read_addr,
    output reg [DATA_WIDTH-1:0] read_data
);parameter DATA_WIDTH = 16;
