module top_module(
  input rst,
  input clk,
  input tclk,
  input measure,
  input echo,
  output reg [15:0] ticks,
  output reg valid,
  output reg trigger
);parameter TRIGGER_DURATION = 1;
  parameter MAX_COUNT = 3800;

  reg [15:0] count;
  reg [15:0] trigger_count;
  reg [15:0] echo_count;

  always @(posedge tclk) begin
    if (rst) begin
      count <= 0;
      trigger_count <= 0;
      echo_count <= 0;
      trigger <= 0;
      valid <= 0;
      ticks <= 0;
    end else begin
      if (measure) begin
        trigger_count <= trigger_count + 1;
        if (trigger_count == TRIGGER_DURATION) begin
          trigger_count <= 0;
          trigger <= 1;
        end else if (trigger_count == TRIGGER_DURATION + 1) begin
          trigger <= 0;
          count <= 0;
        end
      end else begin
        if (echo) begin
          echo_count <= 0;
        end else begin
          echo_count <= echo_count + 1;
          if (echo_count == MAX_COUNT) begin
            valid <= 0;
          end
        end
        if (count > 0) begin
          count <= count - 1;
        end else if (trigger) begin
          count <= MAX_COUNT;
        end else if (!echo) begin
          valid <= 1;
          ticks <= MAX_COUNT - count;
        end
      end
    end
  end

endmodule

