	reg [WIDTH-1:0] c1_fraction;
	reg [31:0] c1_exponent;

	always@(posedge clock or negedge resetn)
	begin
		if (~resetn)
		begin
		end
		else if (c1_enable)
		begin
			c1_valid <= valid_in;
			if (WIDTH==32)
			begin
			  if (~(|dataa[WIDTH-2:WIDTH-9]))
				begin
					c1_fraction <= 32'd0;
					c1_exponent <= 32'd0;
				end
        else if (&dataa[WIDTH-2:WIDTH-9])
				begin
					c1_fraction <= dataa;
					c1_exponent <= 32'd0;
				end
