module fsm (
	input clk,
	input reset,
	input x,
	input y,
	output reg m);

	parameter A=0, B=1, C1=2, C2=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= A;
		else state <= next;
	end

	always_comb begin
		case (state)
			A: next = x ? B : A;
			B: next = y ? C1 : C2;
			C1: next = x ? B : A;
			C2: next = x ? B : A;
			default: next = 'x;
		endcase
	end

	assign m = (state == C1 && y);

endmodule

