module counter_10bit_sync_load(clk, rst, load, init_val, count);
    input clk;
    input rst;
    input load;
    input [9:0] init_val;
    output reg [9:0] count;

    always @(posedge clk) begin
        if (rst)
            count <= 10'b0;
        else if (load)
            count <= init_val;
        else
            count <= count + 1;
    end
endmodule

