description:
Design a pulse-width modulation (PWM) generator that modulates an output signal based on an 8-bit duty cycle provided as input. The module operates on a clock frequency of 50 MHz, generating a PWM signal at a frequency of 10 kHz. It utilizes an 8-bit resolution to determine the duty cycle, where the output signal (pwm_out) is high for a duration proportional to the duty cycle value and low for the remainder of the PWM period. The internal counter increments with each clock cycle, and a comparator evaluates whether the counter value is less than the calculated threshold for generating the high output signal.
module top_module(
  input clk,
  input [7:0] data,
  output pwm_out
);

code:
module top_module(
  input clk,
  input [7:0] data,
  output pwm_out
);parameter clk_freq = 50_000_000; // 50 MHz
parameter pwm_freq = 10_000; // 10 KHz
parameter resolution = 8; // 8-bit duty cycle resolution

reg [resolution-1:0] duty_cycle;
reg [31:0] counter;
wire comparator_out;

assign pwm_out = comparator_out;

always @(posedge clk) begin
  counter <= counter + 1;
  if (counter >= ((clk_freq/pwm_freq)/2)) begin
    counter <= 0;
  end
end

always @(posedge clk) begin
  duty_cycle <= data;
end

assign comparator_out = (counter < ((clk_freq/pwm_freq)*duty_cycle/(2**resolution)));

endmodule

