description:
Implement the Verilog module based on the following description.
Module K implements the boolean function u = (r & ~s).

// Module L can be described by the following simulation waveform: 

If r = 1, s = 1, then u = 0.
If r = 0, s = 1, then u = 0.
If r = 0, s = 0, then u = 0.
If r = 1, s = 0, then u = 1.

// Now consider a top-level that uses three K submodules and two L submodules. The first input of all submodules is connected to input 'w', and the second input of all submodules is connected to 'x'. The output of the first K submodule is connected to a two-input OR gate with the output of the first L submodule. The second and third K submodules' outputs are connected to an AND gate. The output of the OR and the AND gates are connected to a final XOR gate whose output is 'u'.

// Implement this circuit in Verilog.

module top_module(
    input w,
    input x,
    output u);

code:
module K(
    input w,
    input x,
    output u
);
    assign u = (w & ~x);
endmodule

module L(
    input w,
    input x,
    output u
);
    assign u = (w & ~x);
endmodule

module top_module(
    input w,
    input x,
    output u
);
    wire k1_out, k2_out, k3_out, l1_out, l2_out;
    wire or_out, and_out;

    K k1(.w(w), .x(x), .u(k1_out));
    K k2(.w(w), .x(x), .u(k2_out));
    K k3(.w(w), .x(x), .u(k3_out));
    L l1(.w(w), .x(x), .u(l1_out));
    L l2(.w(w), .x(x), .u(l2_out));

    assign or_out = k1_out | l1_out;
    assign and_out = k2_out & k3_out;

    assign u = or_out ^ and_out;
endmodule

