				Hex1 <= six;
				Hex2 <= blank;
			end
			7: begin
				Hex1 <= seven;
				Hex2 <= blank;
			end
			8: begin
				Hex1 <= eight;
				Hex2 <= blank;
			end
			9: begin
				Hex1 <= nine;
				Hex2 <= blank;
			end
			10: begin
				Hex1 <= zero;
				Hex2 <= one;
			end
			11: begin
				Hex1 <= one;
