			14: begin
				Hex1 <= four;
				Hex2 <= one;
			end
			15: begin
				Hex1 <= five;
				Hex2 <= one;
			end
			default: begin
				Hex1 <= blank;
				Hex2 <= blank;
			end
		endcase
	end
endmodule

