description:
Implement the Verilog module based on the following description.
Build a 4-bit binary counter with synchronous active high reset signal and a pause enable signal. When pause is high, the counter stops counting.
// (1) reset: Resets the counter to 4'b0000 when high.
// (2) pause: Pauses the counter increment operation when high.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    input pause,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset,
    input pause,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else if (!pause) begin
            // Counter increment: Increment by 1 when not paused
            q <= q + 1;
        end
    end

endmodule

