module top_module(
  input clk,
  input rst,
  input signed [15:0] x,
  input signed [15:0] d,
  output reg signed [15:0] y // changed to reg to allow assignments in always block
);parameter n = 32; // number of filter taps
parameter mu = 16'h0001; // step size parameter for LMS algorithm, changed to fixed-point representation

reg signed [15:0] w [0:n-1]; // filter coefficients
reg signed [15:0] x_buf [0:n-1]; // buffer to store past input samples
integer i;
reg signed [31:0] error;
reg signed [31:0] y_temp;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    for (i = 0; i < n; i = i + 1) begin
      w[i] <= 0;
      x_buf[i] <= 0;
    end
    y <= 0; // Initialize y on reset
  end else begin
    // Shift input samples in the buffer
    for (i = n-1; i > 0; i = i - 1) begin
      x_buf[i] <= x_buf[i-1];
    end
    x_buf[0] <= x;

    // Compute the output signal y
    y_temp = 0; // Initialize y_temp to 0
    for (i = 0; i < n; i = i + 1) begin
      y_temp = y_temp + (w[i] * x_buf[i]);
    end
    y <= y_temp[31:16]; // Keep y as a reg to allow assignment

    // Compute the error
    error = (d - y); // Assign error as signed operation

    // Update the filter coefficients using the LMS algorithm
    for (i = 0; i < n; i = i + 1) begin
      w[i] <= w[i] + (($signed(mu) * error * x_buf[i]) >>> 16); // Added $signed cast
    end
  end
end

endmodule

