description:
Design a clock generator module that produces a clock signal with a defined period while being able to reset its output. The clock output toggles at half the defined clock period when the reset input is not active. Upon activation of the reset signal, the clock counter and output are reset to their initial states. This module is essential for providing synchronized timing signals for other digital components in a system.
module top_module(
    input reset,
    output reg clk
);

code:
module top_module(
    input reset,
    output reg clk
);// Define the clock period
    localparam PERIOD = 10;

    // Define the clock half period
    localparam HALF_PERIOD = PERIOD / 2;

    // Define the clock counter
    reg [31:0] counter = 0;

    // Generate the clock signal
    always @(posedge reset or negedge clk) begin
        if (reset) begin
            // Reset the clock counter and output
            counter <= 0;
            clk <= 0;
        end else begin
            // Increment the clock counter
            counter <= counter + 1;

            // Toggle the clock output at the half period
            if (counter == HALF_PERIOD) begin
                clk <= ~clk;
            end
        end
    end

endmodule

