module fsm_module (
        input clk,
        input reset,
        input en,
        output reg out);parameter ST0=0, ST1=1, ST2=2, ST3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= ST0;
		else state <= next;


	always_comb begin
		case (state)
			ST0: next = en ? ST1 : ST0;
			ST1: next = en ? ST2 : ST1;
			ST2: next = en ? ST3 : ST2;
			ST3: next = en ? ST0 : ST3;
			default: next = 'x;
		endcase
	end

	assign out = (state == ST1) || (state == ST3);

endmodule

