module sequence_detector (
    input clk,
    input in,
    input reset,
    output seq_detected);parameter S0=0, S1=1, S00=2, S001=3, S0011=4;
    reg [2:0] state;
    reg [2:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S0 : S1;
            S1: next = in ? S0 : S00;
            S00: next = in ? S001 : S0;
            S001: next = in ? S0011 : S0;
            S0011: next = in ? S0 : S1;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign seq_detected = (state == S0011);

endmodule

