module top_module(clk,rst,led_out);input clk,rst;
	output led_out; 

	reg led_reg;	 
	reg [31:0] timer; 


	parameter time_1s = 32'd49_999_999;




	always@(posedge clk or negedge rst)
	begin
		if(rst == 0) 
			begin 
				led_reg <= 1'b0;
				timer <= 32'b0;
			end
		else if(timer == time_1s)
			begin
				led_reg <= ~led_reg;
				timer <= 32'b0;
			end
		else
			timer <= timer + 1'b1;
	end

	assign led_out = led_reg;
endmodule

